// ---------- static environment ----------
let envGroup = null, envKey = '';
function layoutFor(S) { const L = S.trackLength; return { L, x0: -L / 2, x1: L / 2, wallX: L / 2 - 8, runEnd: L / 2 + 11, frontStart: -L / 2 + 1.2 + S.carLength }; }
function planeXZ(x0, x1, z0, z1, y, tile) {
  const g = new THREE.PlaneGeometry(x1 - x0, z1 - z0); g.rotateX(-Math.PI / 2); g.translate((x0 + x1) / 2, y, (z0 + z1) / 2);
  const uv = g.attributes.uv;
  for (let i = 0; i < uv.count; i++) uv.setXY(i, (uv.getX(i) * (x1 - x0) + x0) / tile, (uv.getY(i) * (z1 - z0) + z0) / tile);
  return g;
}
function boxAt(w, h, d, x, y, z) { const g = new THREE.BoxGeometry(w, h, d); g.translate(x, y, z); return g; }
function buildEnvironment(S) {
  const lay = layoutFor(S); const key = lay.L + '|' + S.carLength;
  if (key === envKey) return; envKey = key;
  if (envGroup) { scene.remove(envGroup); envGroup.traverse(o => { if (o.isMesh) o.geometry.dispose(); }); }
  envGroup = new THREE.Group(); scene.add(envGroup);
  const B = new Map();
  const add = (m, g) => { const n = g.index ? g.toNonIndexed() : g; if (!B.has(m)) B.set(m, []); B.get(m).push(n); };
  const { x0, x1, runEnd, frontStart } = lay; const TW = 5;
  add(M.grass, planeXZ(-300, 300, -300, 300, -0.03, 7));
  add(M.asphalt, planeXZ(x0 - 3, x1, -TW, TW, 0, 7));
  add(M.gravel, planeXZ(x1, runEnd + 1.5, -7.5, 7.5, 0, 4));
  for (const s of [1, -1]) {
    const a = s * (TW + 0.7), b = s * (TW + 1.8);
    add(M.gravel, planeXZ(x0 - 3, x1, Math.min(a, b), Math.max(a, b), -0.012, 4));
    const la = s * (TW - 0.32), lb = s * (TW - 0.17);
    add(M.line, planeXZ(x0 - 3, x1, Math.min(la, lb), Math.max(la, lb), 0.003, 1));
  }
  for (let x = x0; x < x1 - 2; x += 6) add(M.line, planeXZ(x, x + 3, -0.06, 0.06, 0.003, 1));
  const sl = frontStart + 0.35, sq = 0.25;
  for (let i = 0; i < Math.round(2 * TW / sq); i++) for (let r = 0; r < 2; r++) if ((i + r) % 2 === 0) add(M.line, planeXZ(sl + r * sq, sl + (r + 1) * sq, -TW + i * sq, -TW + (i + 1) * sq, 0.0035, 1));
  const gb0 = frontStart - S.carLength - 0.5, gz0 = CAR_Z - 1.35, gz1 = CAR_Z + 1.35;
  add(M.line, planeXZ(gb0, gb0 + 0.12, gz0, gz1, 0.003, 1));
  add(M.line, planeXZ(gb0, frontStart + 0.1, gz0, gz0 + 0.12, 0.003, 1));
  add(M.line, planeXZ(gb0, frontStart + 0.1, gz1 - 0.12, gz1, 0.003, 1));
  let k = 0;
  for (let x = x0 - 3; x < x1 - 0.01; x += 1, k++) { const w = Math.min(1, x1 - x); for (const s of [1, -1]) add(k % 2 ? M.curbW : M.curbR, boxAt(w, 0.05, 0.7, x + w / 2, 0.025, s * (TW + 0.35))); }
