// ---------- simulation ----------
function jointForce(c) {
  const e = c.equations;
  const lin = Math.hypot(e[0].multiplier, e[1].multiplier, e[2].multiplier);
  let rot = 0; for (let i = 3; i < e.length; i++) { const m = Math.abs(e[i].multiplier); if (m > rot) rot = m; }
  return { lin, f: lin + rot * 2 };
}
function makeLooseWheel(p) {
  if (p.loose) return; p.loose = true;
  p.ball.radius = 0.02; p.ball.updateBoundingSphereRadius();
  p.cyl.collisionFilterMask = -1;
  p.body.updateBoundingRadius(); p.body.aabbNeedsUpdate = true; p.body.angularDamping = 0.03;
