function setDebris(p) { const b = p.body; b.collisionFilterGroup = G_DEBRIS; b.collisionFilterMask = G_ALL; b.wakeUp(); }
function releaseSubtree(p) {
  p.attached = false; setDebris(p);
  if (p.kind === 'wheel') makeLooseWheel(p);
  for (const ch of p.children) if (ch.parentJoint && !ch.parentJoint.broken) releaseSubtree(ch);
}
