+    if (!orbitInit) { camera.up.set(0, 1, 0); camera.position.set(R.wallX - 13, 7.5, 16); controls.target.set(R.wallX - 3, 0.8, CAR_Z); controls.autoRotate = true; orbitInit = true; }
+    controls.update(); return;
+  }
+  const cab = R.cabin.obj.position;
+  const wallC = _wc.set(R.wallX + R.wallDepthM / 2, Math.min(R.wallHeight, 1.8) * 0.5, 0);
+  let k = 1 - Math.exp(-dtR * 3.2);
+  if (camMode === 'impact') {
+    const sep = Math.hypot(cab.x - wallC.x, cab.z - wallC.z);
+    _dl.copy(cab).lerp(wallC, 0.5); _dl.y = 0.7;
+    _dp.copy(_dl).addScaledVector(CINE_DIR, clamp(7.5 + sep * 0.62, 11.5, 25));
+  } else if (camMode === 'follow') {
+    _dp.set(cab.x - 7.2, cab.y + 2.4, cab.z + 2.6); _dl.set(cab.x + 4, 0.8, cab.z * 0.5); k = 1 - Math.exp(-dtR * 6);
+  } else {
+    const lay = R.lay, cx = (lay.x0 - 3 + lay.runEnd) / 2, span = lay.runEnd - (lay.x0 - 3) + 4;
+    const t = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
+    _dp.set(cx, Math.max((span / 2) / (t * camera.aspect), 10 / t) * 1.02, 0.001); _dl.set(cx, 0, 0); k = 1;
+  }
+  if (camSnap) { camPos.copy(_dp); camLook.copy(_dl); camSnap = false; } else { camPos.lerp(_dp, k); camLook.lerp(_dl, k); }
+  if (camMode === 'top') camera.up.set(0, 0, -1); else camera.up.set(0, 1, 0);
+  camera.position.copy(camPos);
+  if (R.shake > 0.002 && camMode !== 'top') {
+    const t = R.time;
+    camera.position.x += Math.sin(t * 71.3) * R.shake * 0.35;
+    camera.position.y += Math.sin(t * 93.7 + 1.3) * R.shake * 0.3;
+    camera.position.z += Math.sin(t * 57.1 + 2.1) * R.shake * 0.25;
