+}
+
+// tight, texel-snapped shadow frustum around the car, wall and debris
+let sunS = 0;
+const _lf = new THREE.Vector3(), _lr = new THREE.Vector3(), _lu = new THREE.Vector3(), _lc = new THREE.Vector3(), UP = new THREE.Vector3(0, 1, 0);
+function updateSun(R) {
+  let x0 = R.wallX - 1, x1 = R.wallX + R.wallDepthM + 1, z0 = -R.wallWidth / 2 - 1, z1 = R.wallWidth / 2 + 1;
+  const inc = p => { if (p.x < x0) x0 = p.x; if (p.x > x1) x1 = p.x; if (p.z < z0) z0 = p.z; if (p.z > z1) z1 = p.z; };
+  for (const p of R.parts) inc(p.body.position);
+  for (const b of R.bricks) inc(b.position);
+  let S = Math.ceil(clamp(Math.max(x1 - x0, z1 - z0) / 2 + 3, 8, 30));
+  if (S !== sunS) { sc.left = -S; sc.right = S; sc.top = S; sc.bottom = -S; sc.updateProjectionMatrix(); sunS = S; }
+  _lf.copy(SUN_DIR).negate(); _lr.crossVectors(_lf, UP).normalize(); _lu.crossVectors(_lr, _lf);
+  _lc.set((x0 + x1) / 2, 0.8, (z0 + z1) / 2);
+  const texel = 2 * S / sun.shadow.mapSize.x;
+  const dr = Math.round(_lc.dot(_lr) / texel) * texel, du = Math.round(_lc.dot(_lu) / texel) * texel, df = _lc.dot(_lf);
+  _lc.copy(_lr).multiplyScalar(dr).addScaledVector(_lu, du).addScaledVector(_lf, df);
+  sun.target.position.copy(_lc); sun.position.copy(_lc).addScaledVector(SUN_DIR, 60);
+}
+
+// ---------- UI ----------
+const $ = id => document.getElementById(id);
+const panelBody = $('panelBody');
+{
+  let html = '';
+  for (const [grp, fields] of FIELDS) {
+    html += `<div class="grp"><h4>${grp}</h4>`;
+    for (const [key, label, unit, min, max, step] of fields) html += `<label><span>${label}${unit ? ` <em>${unit}</em>` : ''}</span><input type="number" id="f_${key}" min="${min}" max="${max}" step="${step}" value="${DEFAULTS[key]}"></label>`;
+    html += '</div>';
+  }
+  html += '<div class="actions"><button id="defaults">Defaults</button><button id="apply" class="primary">Apply &amp; run</button></div>';
+  panelBody.innerHTML = html;
+}
+function readSettings() {
+  const S = {};
+  for (const [, fields] of FIELDS) for (const [key, , , min, max, , isInt] of fields) {
+    const el = $('f_' + key); let v = parseFloat(el.value);
+    if (!isFinite(v)) v = DEFAULTS[key];
+    v = clamp(v, min, max); if (isInt) v = Math.round(v);
+    el.value = v; S[key] = v;
+  }
+  return S;
+}
+function replay() { buildRun(readSettings()); }
+function setPaused(p) {
+  paused = p;
+  $('playIcon').setAttribute('d', p ? 'M7 5l12 7-12 7z' : 'M7 5h3.5v14H7zM13.5 5H17v14h-3.5z');
+  $('playLbl').textContent = p ? 'Play' : 'Pause';
+}
+function setCam(m) {
+  if (m === camMode) return;
+  camMode = m; controls.enabled = m === 'orbit'; camSnap = true;
+  if (m === 'orbit' && orbitInit) camera.up.set(0, 1, 0);
+  document.querySelectorAll('#camSeg button').forEach(b => b.classList.toggle('on', b.dataset.v === m));
+}
+function setSpeed(v) { simSpeed = v; document.querySelectorAll('#speedSeg button').forEach(b => b.classList.toggle('on', parseFloat(b.dataset.v) === v)); }
+const blurThen = fn => e => { e.currentTarget.blur(); fn(e); };
+$('replay').onclick = blurThen(replay);
+$('play').onclick = blurThen(() => setPaused(!paused));
+$('apply').onclick = blurThen(replay);
+$('defaults').onclick = blurThen(() => { for (const [, fields] of FIELDS) for (const [key] of fields) $('f_' + key).value = DEFAULTS[key]; });
+$('settingsBtn').onclick = blurThen(() => $('panel').classList.toggle('open'));
+$('closePanel').onclick = blurThen(() => $('panel').classList.remove('open'));
+document.querySelectorAll('#speedSeg button').forEach(b => b.onclick = blurThen(() => setSpeed(parseFloat(b.dataset.v))));
+document.querySelectorAll('#camSeg button').forEach(b => b.onclick = blurThen(() => setCam(b.dataset.v)));
+panelBody.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.tagName === 'INPUT') replay(); });
+addEventListener('keydown', e => {
+  const ae = document.activeElement, inNum = ae && ae.tagName === 'INPUT' && ae.type === 'number';
+  if (e.code === 'Space') { if (inNum) return; e.preventDefault(); setPaused(!paused); return; }
+  if (inNum) return;
+  if (e.key === 'r' || e.key === 'R') replay();
+  const cams = ['impact', 'follow', 'top', 'orbit']; const n = parseInt(e.key, 10);
+  if (n >= 1 && n <= 4) setCam(cams[n - 1]);
+});
+function updateFxScale() { const s = renderer.domElement.height / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2))); for (const f of [dust, sparks, glassFx]) f.mat.uniforms.uScale.value = s; }
+addEventListener('resize', () => { renderer.setSize(innerWidth, innerHeight); camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix(); updateFxScale(); });
+updateFxScale();
+
+// ---------- main loop ----------
+const hud = { T: $('hT'), V: $('hV'), I: $('hI'), J: $('hJ'), B: $('hB'), S: $('hS') };
+let last = performance.now(), hudT = 0;
+function updateHud(R) {
+  const cb = R.cabin.body, v = cb.velocity.length();
+  hud.T.textContent = R.time.toFixed(2) + ' s';
+  hud.V.textContent = v.toFixed(1) + ' m/s \u00b7 ' + Math.round(v * 3.6) + ' km/h';
+  hud.I.textContent = R.impactSpeed === null ? '\u2013' : R.impactSpeed.toFixed(1) + ' m/s';
+  hud.J.textContent = R.brokenCount;
+  let moved = 0; for (const b of R.bricks) { const s = b.vis.spawn; if (Math.abs(b.position.x - s.x) + Math.abs(b.position.y - s.y) + Math.abs(b.position.z - s.z) > 0.1) moved++; }
+  hud.B.textContent = moved + ' / ' + R.bricks.length;
+  hud.S.textContent = paused ? 'Paused' : !R.impact ? 'Approach' : R.frozen ? 'Settled' : 'Impact';
+}
+function frame(now) {
+  requestAnimationFrame(frame);
+  const dtR = Math.min(0.1, (now - last) / 1000); last = now;
+  const R = run; if (!R) return;
+  if (!paused && !R.frozen) {
+    acc += dtR * simSpeed; let n = 0;
+    while (acc >= DT && n < MAX_STEPS) { stepSim(R); acc -= DT; n++; }
+    if (n >= MAX_STEPS && acc > DT) acc = DT * 0.5;
+  }
+  syncVisuals(R, R.frozen ? 1 : clamp(acc / DT, 0, 1));
+  const pdt = paused ? 0 : dtR * simSpeed;
+  dust.update(pdt); sparks.update(pdt); glassFx.update(pdt);
+  updateCamera(R, dtR); updateSun(R);
+  sky.position.copy(camera.position);
+  renderer.render(scene, camera);
+  hudT += dtR; if (hudT > 0.1) { hudT = 0; updateHud(R); }
+}
+buildRun({ ...DEFAULTS });
+requestAnimationFrame(frame);
 </script>
